%dw 2.0
output application/json
---
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "result": {
        "tools": [
            {
                "name": "get_current_time",
                "description": "Get the current date and time for a city or timezone. Returns formatted local time with timezone abbreviation.",
                "inputSchema": {
                    "type": "object",
                    "properties": {
                        "city": {
                            "type": "string",
                            "description": "City name (e.g., 'Tokyo', 'New York', 'London') or IANA timezone ID (e.g., 'America/New_York')"
                        }
                    },
                    "required": ["city"]
                }
            },
            {
                "name": "convert_time",
                "description": "Convert a specific time from one timezone to another. Useful for scheduling meetings across timezones.",
                "inputSchema": {
                    "type": "object",
                    "properties": {
                        "time": {
                            "type": "string",
                            "description": "Time to convert in HH:mm format (24-hour) e.g., '14:30' or '09:00'"
                        },
                        "from_city": {
                            "type": "string",
                            "description": "Source city or timezone (e.g., 'New York', 'Asia/Tokyo')"
                        },
                        "to_city": {
                            "type": "string",
                            "description": "Target city or timezone (e.g., 'London', 'Europe/Paris')"
                        }
                    },
                    "required": ["time", "from_city", "to_city"]
                }
            },
            {
                "name": "time_difference",
                "description": "Get the time difference in hours between two cities. Shows which city is ahead and by how many hours.",
                "inputSchema": {
                    "type": "object",
                    "properties": {
                        "city1": {
                            "type": "string",
                            "description": "First city or timezone (e.g., 'New York', 'America/Chicago')"
                        },
                        "city2": {
                            "type": "string",
                            "description": "Second city or timezone (e.g., 'Tokyo', 'Asia/Kolkata')"
                        }
                    },
                    "required": ["city1", "city2"]
                }
            },
            {
                "name": "list_timezones",
                "description": "List available timezones, optionally filtered by region. Regions include: America, Europe, Asia, Africa, Australia, Pacific.",
                "inputSchema": {
                    "type": "object",
                    "properties": {
                        "region": {
                            "type": "string",
                            "description": "Optional region filter (e.g., 'Asia', 'Europe', 'America'). If omitted, returns all supported cities."
                        }
                    },
                    "required": []
                }
            }
        ]
    }
}

%dw 2.0 output application/json
var cityMap = { "new york": "America/New_York", "nyc": "America/New_York", "los angeles": "America/Los_Angeles", "la": "America/Los_Angeles", "san francisco": "America/Los_Angeles", "sf": "America/Los_Angeles", "chicago": "America/Chicago", "denver": "America/Denver", "phoenix": "America/Phoenix", "houston": "America/Chicago", "dallas": "America/Chicago", "miami": "America/New_York", "seattle": "America/Los_Angeles", "boston": "America/New_York", "washington dc": "America/New_York", "dc": "America/New_York", "atlanta": "America/New_York", "toronto": "America/Toronto", "vancouver": "America/Vancouver", "mexico city": "America/Mexico_City", "sao paulo": "America/Sao_Paulo", "buenos aires": "America/Argentina/Buenos_Aires", "london": "Europe/London", "paris": "Europe/Paris", "berlin": "Europe/Berlin", "madrid": "Europe/Madrid", "rome": "Europe/Rome", "amsterdam": "Europe/Amsterdam", "zurich": "Europe/Zurich", "moscow": "Europe/Moscow", "istanbul": "Europe/Istanbul", "dubai": "Asia/Dubai", "abu dhabi": "Asia/Dubai", "riyadh": "Asia/Riyadh", "mumbai": "Asia/Kolkata", "delhi": "Asia/Kolkata", "bangalore": "Asia/Kolkata", "chennai": "Asia/Kolkata", "kolkata": "Asia/Kolkata", "karachi": "Asia/Karachi", "dhaka": "Asia/Dhaka", "bangkok": "Asia/Bangkok", "singapore": "Asia/Singapore", "kuala lumpur": "Asia/Kuala_Lumpur", "jakarta": "Asia/Jakarta", "hong kong": "Asia/Hong_Kong", "shanghai": "Asia/Shanghai", "beijing": "Asia/Shanghai", "taipei": "Asia/Taipei", "seoul": "Asia/Seoul", "tokyo": "Asia/Tokyo", "sydney": "Australia/Sydney", "melbourne": "Australia/Melbourne", "brisbane": "Australia/Brisbane", "perth": "Australia/Perth", "auckland": "Pacific/Auckland", "honolulu": "Pacific/Honolulu", "hawaii": "Pacific/Honolulu" }
var inputCity = lower(vars.arguments.city default "") var timezone = cityMap[inputCity] default vars.arguments.city var currentTime = now() >> (timezone as TimeZone) var formatted = currentTime as String {format: "EEEE, MMMM d, yyyy h:mm:ss a"} var tzAbbr = currentTime as String {format: "z"} --- { "jsonrpc": "2.0", "id": vars.requestId, "result": { "content": [ { "type": "text", "text": formatted ++ " " ++ tzAbbr ++ " (" ++ timezone ++ ")" } ] } }

%dw 2.0 output application/json
var cityMap = { "new york": "America/New_York", "nyc": "America/New_York", "los angeles": "America/Los_Angeles", "la": "America/Los_Angeles", "san francisco": "America/Los_Angeles", "sf": "America/Los_Angeles", "chicago": "America/Chicago", "denver": "America/Denver", "phoenix": "America/Phoenix", "houston": "America/Chicago", "dallas": "America/Chicago", "miami": "America/New_York", "seattle": "America/Los_Angeles", "boston": "America/New_York", "washington dc": "America/New_York", "dc": "America/New_York", "atlanta": "America/New_York", "toronto": "America/Toronto", "vancouver": "America/Vancouver", "mexico city": "America/Mexico_City", "sao paulo": "America/Sao_Paulo", "buenos aires": "America/Argentina/Buenos_Aires", "london": "Europe/London", "paris": "Europe/Paris", "berlin": "Europe/Berlin", "madrid": "Europe/Madrid", "rome": "Europe/Rome", "amsterdam": "Europe/Amsterdam", "zurich": "Europe/Zurich", "moscow": "Europe/Moscow", "istanbul": "Europe/Istanbul", "dubai": "Asia/Dubai", "abu dhabi": "Asia/Dubai", "riyadh": "Asia/Riyadh", "mumbai": "Asia/Kolkata", "delhi": "Asia/Kolkata", "bangalore": "Asia/Kolkata", "chennai": "Asia/Kolkata", "kolkata": "Asia/Kolkata", "karachi": "Asia/Karachi", "dhaka": "Asia/Dhaka", "bangkok": "Asia/Bangkok", "singapore": "Asia/Singapore", "kuala lumpur": "Asia/Kuala_Lumpur", "jakarta": "Asia/Jakarta", "hong kong": "Asia/Hong_Kong", "shanghai": "Asia/Shanghai", "beijing": "Asia/Shanghai", "taipei": "Asia/Taipei", "seoul": "Asia/Seoul", "tokyo": "Asia/Tokyo", "sydney": "Australia/Sydney", "melbourne": "Australia/Melbourne", "brisbane": "Australia/Brisbane", "perth": "Australia/Perth", "auckland": "Pacific/Auckland", "honolulu": "Pacific/Honolulu", "hawaii": "Pacific/Honolulu" }
var fromInput = lower(vars.arguments.from_city default "") var toInput = lower(vars.arguments.to_city default "") var fromTz = cityMap[fromInput] default vars.arguments.from_city var toTz = cityMap[toInput] default vars.arguments.to_city var inputTime = vars.arguments.time default "12:00"
var sourceDateTime = if (inputTime contains "T") inputTime as LocalDateTime else ((now() as Date) as String ++ "T" ++ inputTime ++ (if (inputTime contains ":") "" else ":00") ++ ":00") as LocalDateTime var sourceZoned = sourceDateTime >> (fromTz as TimeZone) var targetZoned = sourceZoned >> (toTz as TimeZone)
var sourceFormatted = sourceZoned as String {format: "h:mm a z"} var targetFormatted = targetZoned as String {format: "h:mm a z"} var targetDate = targetZoned as Date var dayDiff = (targetDate - (sourceZoned as Date)) as Number var dayNote = if (dayDiff > 0) " (next day)" else if (dayDiff < 0) " (previous day)" else "" --- { "jsonrpc": "2.0", "id": vars.requestId, "result": { "content": [ { "type": "text", "text": sourceFormatted ++ " = " ++ targetFormatted ++ dayNote } ] } }

%dw 2.0 output application/json
fun parseOffsetMinutes(offset) = do { var sign = if (offset[0] == "-") -1 else 1 var parts = (offset[1 to -1]) splitBy ":" var hours = parts[0] as Number var mins = parts[1] as Number --- sign * (hours * 60 + mins) }
var cityMap = { "new york": "America/New_York", "nyc": "America/New_York", "los angeles": "America/Los_Angeles", "la": "America/Los_Angeles", "san francisco": "America/Los_Angeles", "sf": "America/Los_Angeles", "chicago": "America/Chicago", "denver": "America/Denver", "phoenix": "America/Phoenix", "houston": "America/Chicago", "dallas": "America/Chicago", "miami": "America/New_York", "seattle": "America/Los_Angeles", "boston": "America/New_York", "washington dc": "America/New_York", "dc": "America/New_York", "atlanta": "America/New_York", "toronto": "America/Toronto", "vancouver": "America/Vancouver", "mexico city": "America/Mexico_City", "sao paulo": "America/Sao_Paulo", "buenos aires": "America/Argentina/Buenos_Aires", "london": "Europe/London", "paris": "Europe/Paris", "berlin": "Europe/Berlin", "madrid": "Europe/Madrid", "rome": "Europe/Rome", "amsterdam": "Europe/Amsterdam", "zurich": "Europe/Zurich", "moscow": "Europe/Moscow", "istanbul": "Europe/Istanbul", "dubai": "Asia/Dubai", "abu dhabi": "Asia/Dubai", "riyadh": "Asia/Riyadh", "mumbai": "Asia/Kolkata", "delhi": "Asia/Kolkata", "bangalore": "Asia/Kolkata", "chennai": "Asia/Kolkata", "kolkata": "Asia/Kolkata", "karachi": "Asia/Karachi", "dhaka": "Asia/Dhaka", "bangkok": "Asia/Bangkok", "singapore": "Asia/Singapore", "kuala lumpur": "Asia/Kuala_Lumpur", "jakarta": "Asia/Jakarta", "hong kong": "Asia/Hong_Kong", "shanghai": "Asia/Shanghai", "beijing": "Asia/Shanghai", "taipei": "Asia/Taipei", "seoul": "Asia/Seoul", "tokyo": "Asia/Tokyo", "sydney": "Australia/Sydney", "melbourne": "Australia/Melbourne", "brisbane": "Australia/Brisbane", "perth": "Australia/Perth", "auckland": "Pacific/Auckland", "honolulu": "Pacific/Honolulu", "hawaii": "Pacific/Honolulu" }
var input1 = lower(vars.arguments.city1 default "") var input2 = lower(vars.arguments.city2 default "") var tz1 = cityMap[input1] default vars.arguments.city1 var tz2 = cityMap[input2] default vars.arguments.city2
var now1 = now() >> (tz1 as TimeZone) var now2 = now() >> (tz2 as TimeZone) var offset1 = (now1 as String {format: "XXX"}) var offset2 = (now2 as String {format: "XXX"})
var mins1 = parseOffsetMinutes(offset1) var mins2 = parseOffsetMinutes(offset2) var diffMinutes = mins2 - mins1 var diffHours = diffMinutes / 60
var city1Display = vars.arguments.city1 default tz1 var city2Display = vars.arguments.city2 default tz2
var result = if (diffMinutes == 0) city1Display ++ " and " ++ city2Display ++ " are in the same timezone" else if (diffMinutes > 0) city2Display ++ " is " ++ (if (diffHours == floor(diffHours)) (floor(diffHours) as String) else (diffHours as String)) ++ " hours ahead of " ++ city1Display else city2Display ++ " is " ++ (if ((-diffHours) == floor(-diffHours)) (floor(-diffHours) as String) else ((-diffHours) as String)) ++ " hours behind " ++ city1Display --- { "jsonrpc": "2.0", "id": vars.requestId, "result": { "content": [ { "type": "text", "text": result } ] } }

%dw 2.0
output application/json

var allCities = {
    "America": ["New York", "Los Angeles", "Chicago", "Denver", "Phoenix", "Houston", "Dallas", "Miami", "Seattle", "Boston", "Washington DC", "Atlanta", "Toronto", "Vancouver", "Mexico City", "Sao Paulo", "Buenos Aires"],
    "Europe": ["London", "Paris", "Berlin", "Madrid", "Rome", "Amsterdam", "Zurich", "Moscow", "Istanbul"],
    "Asia": ["Dubai", "Abu Dhabi", "Riyadh", "Mumbai", "Delhi", "Bangalore", "Chennai", "Kolkata", "Karachi", "Dhaka", "Bangkok", "Singapore", "Kuala Lumpur", "Jakarta", "Hong Kong", "Shanghai", "Beijing", "Taipei", "Seoul", "Tokyo"],
    "Australia": ["Sydney", "Melbourne", "Brisbane", "Perth"],
    "Pacific": ["Auckland", "Honolulu"]
}

var regionFilter = vars.arguments.region default ""
var filtered = if (regionFilter == "" or regionFilter == null)
    allCities
else
    { (regionFilter): allCities[regionFilter] default [] }

var resultText = filtered pluck ((cities, region) ->
    (region as String) ++ ": " ++ (cities joinBy ", ")
) joinBy "\n"
---
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "result": {
        "content": [
            {
                "type": "text",
                "text": resultText
            }
        ]
    }
}
